const body = $input.first().json.body || $input.first().json;
const tabName  = body.tab_name  || '';
const headers  = body.headers   || [];
const rows     = body.rows      || [];
if (!tabName || !headers.length) {
  throw new Error('Missing tab_name or headers (report_key=' + body.report_key + ')');
}
return [{ json: { tabName, rows, headers } }];

const data = $('Prepare Data').first().json;
const rows = data.rows || [];
const headers = data.headers || [];
if (!rows.length) return [];
return rows.map(row => {
  const obj = {};
  for (const h of headers) {
    const val = row[h];
    obj[h] = (val === null || val === undefined) ? '' : String(val);
  }
  return { json: obj };
});

